class CrossCheck(unittest.TestCase):
    def test_matches_datetime_isocalendar(self):
        d = datetime.date(1800, 1, 1)
        end = datetime.date(2200, 12, 31)
        step = datetime.timedelta(days=1)
        while d <= end:
            ref = d.isocalendar()
            got = iso_week(d.year, d.month, d.day)
            self.assertEqual(got, tuple(ref), d)
            back = from_iso(*got)
            self.assertEqual(back, (d.year, d.month, d.day), d)
            d += step

    def test_from_iso_rejects_every_nonexistent_week(self):
        for y in range(1800, 2200):
            weeks = datetime.date(y, 12, 28).isocalendar()[1]
            for w in range(1, 54):
                for wd in range(1, 8):
                    if w > weeks:
                        with self.assertRaises(ValueError):
                            from_iso(y, w, wd)


